import{_ as a,o as e,c as d,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const b=JSON.parse('{"title":"基础教程","description":"","frontmatter":{},"headers":[],"relativePath":"basic/index.md","filePath":"basic/index.md","lastUpdated":1790938575000}'),i={name:"basic/index.md"};function s(h,t,o,n,l,c){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="基础教程" tabindex="-1">基础教程 <a class="header-anchor" href="#基础教程" aria-label="Permalink to &quot;基础教程&quot;">​</a></h1><p>ZViewer 是多人同步观影、追番与远程共享平台。本章节为基础教程，大部分人使用这部分即可；项目详细信息见<a href="/advanced/">拓展教程</a>。</p><h2 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h2><h3 id="_1-下载" tabindex="-1">1. 下载 <a class="header-anchor" href="#_1-下载" aria-label="Permalink to &quot;1. 下载&quot;">​</a></h3><p>从 <a href="https://github.com/Zero-wyc/ZViewer/releases" target="_blank" rel="noreferrer">Releases</a> 下载对应系统的压缩包（Windows <code>zviewer-windows-x64.zip</code> / Linux <code>zviewer-linux-x64.tar.gz</code>），解压后运行。</p><h3 id="_2-启动" tabindex="-1">2. 启动 <a class="header-anchor" href="#_2-启动" aria-label="Permalink to &quot;2. 启动&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">start.bat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> #也可以直接双击start.bat文件</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./start.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><h3 id="_3-登录" tabindex="-1">3. 登录 <a class="header-anchor" href="#_3-登录" aria-label="Permalink to &quot;3. 登录&quot;">​</a></h3><p>访问 <code>http://localhost:3333</code>。首次启动自动创建超级管理员：</p><table tabindex="0"><thead><tr><th>用户名</th><th>密码</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>root</code></td></tr></tbody></table><p>生产环境部署后应立即修改默认密码（右上角用户菜单 → 个人资料 → 编辑信息 → 修改密码）。</p><h3 id="_4-创建房间" tabindex="-1">4. 创建房间 <a class="header-anchor" href="#_4-创建房间" aria-label="Permalink to &quot;4. 创建房间&quot;">​</a></h3><p>点击「开始共享」→ 选择模式（一起看 / 投屏）→ 进入房间。将房间信息面板中的房间号或分享链接发给其他用户，对方可通过房间号、房间列表或链接加入。</p><h3 id="_5-添加影片" tabindex="-1">5. 添加影片 <a class="header-anchor" href="#_5-添加影片" aria-label="Permalink to &quot;5. 添加影片&quot;">​</a></h3><p>在「添加影片」面板选择来源：B站（粘贴 BV 号或链接解析）、直链（MP4 等地址）、WebDAV / FTP / OpenList 挂载（先在个人资料页或后台配置）。点击影片开始播放，进度实时同步给所有成员。</p><h2 id="端口" tabindex="-1">端口 <a class="header-anchor" href="#端口" aria-label="Permalink to &quot;端口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>端口</th><th>用途</th><th>对外</th></tr></thead><tbody><tr><td>3333</td><td>统一入口：API、WebSocket、前端页面、<code>/live</code> FLV 代理</td><td>是</td></tr><tr><td>3334</td><td>RTMP 推流（OBS）</td><td>是</td></tr><tr><td>3335</td><td>HTTP-FLV 拉流（内部）</td><td>否</td></tr></tbody></table><h2 id="浏览器要求" tabindex="-1">浏览器要求 <a class="header-anchor" href="#浏览器要求" aria-label="Permalink to &quot;浏览器要求&quot;">​</a></h2><p>使用内核 130+ 的 Chromium 浏览器（Chrome / Edge 等）。Safari 与 Firefox 对 MSE / MKV 解码支持不完整，可能出现卡顿、无法解码、字幕异常。</p><h2 id="本分区目录" tabindex="-1">本分区目录 <a class="header-anchor" href="#本分区目录" aria-label="Permalink to &quot;本分区目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="/basic/install">安装与部署</a></td><td>单文件 / 源码 / Docker / 数据持久化</td></tr><tr><td><a href="/basic/features">功能说明</a></td><td>全部功能的使用说明</td></tr><tr><td><a href="/basic/mobile">手机端 App</a></td><td>Android / HarmonyOS 客户端下载、安装与平台差异</td></tr><tr><td><a href="/basic/cli">ZViewerCLI</a></td><td>本地代理客户端安装与使用</td></tr><tr><td><a href="/basic/admin">管理后台</a></td><td>用户审核、房间管理、系统设置</td></tr><tr><td><a href="/basic/network">网络连接与内网穿透</a></td><td>FRP / ZeroTier / IPv6</td></tr><tr><td><a href="/basic/faq">常见问题</a></td><td>证书、WebSocket、数据库等常见问题</td></tr></tbody></table><p>需要 HTTPS 时，用一键脚本签发并启动（<code>start.bat https</code> / <code>./start.sh https</code>）；证书签发机制与实现细节见 <a href="/advanced/https">HTTPS 证书</a>。（新手建议使用内网穿透的自动https或者配一个本地证书的就可以了，本地证书虽然会弹一个警告，但是无妨）</p><p>相关页面：<a href="/advanced/">拓展教程</a></p>`,23)])])}const k=a(i,[["render",s]]);export{b as __pageData,k as default};
